	}
	fmt.Println("CA_EVENT " + string(b))
}

func assurance2Types(msgs []*pb.Message) []string {
	out := make([]string, 0, len(msgs))
	for _, m := range msgs {
		out = append(out, m.GetType().String())
	}
	return out
}

