		"state":             n2.state.String(),
	}
	if len(n2.readStates) > 0 {
		ev["read_index"] = n2.readStates[len(n2.readStates)-1].Index
		ev["read_index_at_least_own_committed"] = n2.readStates[len(n2.readStates)-1].Index >= n2.raftLog.committed
	}
