		"scenario": "removed-singleton-leader-read",
		"event":                      "second_stale_read",
		"step":                       "read-via-removed-leader-after-heartbeats",
		"node":                       1,
		"request_ctx":                "R2",
		"read_states":                len(n1.readStates),
		"heartbeats_sent":            heartbeats,
