	for _, msg := range emitted {
		if msg.GetType() == pb.MsgHeartbeat {
			heartbeats++
			ctxLen = len(msg.GetContext())
		}
	}
	assurance2Emit(t, map[string]any{
		"scenario":            "removed-non-singleton-leader-read",
		"event":               "b_read_attempt",
